examples.setupTemplate:
val scope = rememberCoroutineScope()
val rules = MonarchPasswordRule.defaults()
val documents = listOf(
    MonarchTermsDocument({{terms.0.label}}, "https://example.com/terms", version = {{terms.0.version}}),
    MonarchTermsDocument({{terms.1.label}}, "https://example.com/privacy", version = {{terms.1.version}}),
)
var name by rememberSaveable { mutableStateOf("") }
var email by rememberSaveable { mutableStateOf({{email}}) }
var password by remember { mutableStateOf("") }
var accepted by rememberSaveable { mutableStateOf(false) }
var tried by rememberSaveable { mutableStateOf(false) }
var emailTaken by remember { mutableStateOf<String?>(null) }
var formError by remember { mutableStateOf<String?>(null) }
var creating by remember { mutableStateOf(false) }
val nameError = "Enter your name.".takeIf { tried && name.isBlank() }
val emailError = emailTaken ?: "Enter an email address like name@example.com."
    .takeIf { tried && ("@" !in email.trim() || "." !in email.trim()) }
val passwordError = "Choose a password that meets every rule.".takeIf { tried && !rules.all { it.test(password) } }
val createAccount = {
    tried = true
    val valid = name.isNotBlank() && "@" in email.trim() && "." in email.trim() && rules.all { it.test(password) }
    if (valid && accepted) {
        creating = true
        scope.launch {
            // The app's request. An email in use sets emailTaken; any other failure sets formError.
            creating = false
        }
    }
}

